Below is a minimal, complete `main.tf` plus the exact commands. Replace the placeholder bucket names (marked `# CHANGE ME`) with real, globally-unique values before running.

## main.tf

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.31"
    }
  }

  backend "s3" {
    bucket = "your-terraform-state-bucket" # CHANGE ME - must already exist
    key    = "envs/prod/terraform.tfstate"
    region = "us-east-1"
    # encrypt = true  # uncomment if your state bucket has SSE enabled
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "this" {
  bucket = "your-new-bucket-name" # CHANGE ME - must be globally unique

  tags = {
    Environment = "prod"
    ManagedBy   = "terraform"
  }
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_name" {
  value = aws_s3_bucket.this.id
}
```

### Notes
- **Backend bucket must pre-exist** — Terraform's S3 backend does not create the state bucket for you. Create it once (manually or via a separate bootstrap script/config) before running `terraform init` here.
- The `backend "s3"` block cannot use variables/interpolation — values must be literal strings, which is why the bucket name is hardcoded rather than parameterized.
- If your state bucket enforces SSE, add `encrypt = true` to the backend block (shown commented out above).

## Commands

```bash
export AWS_PROFILE=prod-deploy

terraform init

terraform apply
```

If you prefer to review the plan first:

```bash
terraform plan -out=tfplan
terraform apply tfplan
```

